/* Advanced SIMD helpers for code generated by recomp.py.
 * Written for correctness first: every helper works element by element. */
#ifndef RECOMP_NEON_H
#define RECOMP_NEON_H

static inline uint64_t vget(const V128 *v, int sz, int i) {
    switch (sz) {
    case 0: return v->b[i];
    case 1: return v->h[i];
    case 2: return v->w[i];
    default: return v->d[i];
    }
}
static inline void vset(V128 *v, int sz, int i, uint64_t x) {
    switch (sz) {
    case 0: v->b[i] = (uint8_t)x; break;
    case 1: v->h[i] = (uint16_t)x; break;
    case 2: v->w[i] = (uint32_t)x; break;
    default: v->d[i] = x; break;
    }
}
static inline int64_t vsext(uint64_t x, int sz) {
    switch (sz) {
    case 0: return (int8_t)x;
    case 1: return (int16_t)x;
    case 2: return (int32_t)x;
    default: return (int64_t)x;
    }
}

/* AArch64 FMAX/FMIN propagate NaN; the NM variants return the number: exact versions in fpexact.h (fp_maxmin32 / 64). */

enum { F_ADD, F_SUB, F_MUL, F_DIV, F_MLA, F_MLS, F_MAX, F_MIN, F_MAXNM, F_MINNM, F_ABD,
       F_CMEQ, F_CMGE, F_CMGT, F_RECPS, F_RSQRTS, F_ADDP };

static inline float f3s(int op, float acc, float a, float b, uint32_t *mask, int *is_mask) {
    switch (op) {
    case F_ADD: return a + b;
    case F_SUB: return a - b;
    case F_MUL: return a * b;
    case F_DIV: return a / b;
    case F_MLA: return fmaf(a, b, acc);
    case F_MLS: return fmaf(-a, b, acc);
    case F_MAX: return fp_maxmin32(a, b, 0, 0);
    case F_MIN: return fp_maxmin32(a, b, 1, 0);
    case F_MAXNM: return fp_maxmin32(a, b, 0, 1);
    case F_MINNM: return fp_maxmin32(a, b, 1, 1);
    case F_ABD: return fabsf(a - b);
    case F_RECPS: return fmaf(-a, b, 2.0f);
    case F_RSQRTS: return fmaf(-a, b, 3.0f) / 2.0f;
    case F_CMEQ: *is_mask = 1; *mask = a == b ? ~0u : 0; return 0;
    case F_CMGE: *is_mask = 1; *mask = a >= b ? ~0u : 0; return 0;
    case F_CMGT: *is_mask = 1; *mask = a > b ? ~0u : 0; return 0;
    }
    return 0;
}
static inline double f3d(int op, double acc, double a, double b, uint64_t *mask, int *is_mask) {
    switch (op) {
    case F_ADD: return a + b;
    case F_SUB: return a - b;
    case F_MUL: return a * b;
    case F_DIV: return a / b;
    case F_MLA: return fma(a, b, acc);
    case F_MLS: return fma(-a, b, acc);
    case F_MAX: return fp_maxmin64(a, b, 0, 0);
    case F_MIN: return fp_maxmin64(a, b, 1, 0);
    case F_MAXNM: return fp_maxmin64(a, b, 0, 1);
    case F_MINNM: return fp_maxmin64(a, b, 1, 1);
    case F_ABD: return fabs(a - b);
    case F_RECPS: return fma(-a, b, 2.0);
    case F_RSQRTS: return fma(-a, b, 3.0) / 2.0;
    case F_CMEQ: *is_mask = 1; *mask = a == b ? ~0ull : 0; return 0;
    case F_CMGE: *is_mask = 1; *mask = a >= b ? ~0ull : 0; return 0;
    case F_CMGT: *is_mask = 1; *mask = a > b ? ~0ull : 0; return 0;
    }
    return 0;
}

/* Floating-point "three same": n elements, upper part of the destination cleared. */
static inline void v_f3v(V128 *d, const V128 *pn, const V128 *pm, int op, int dbl, int n) {
    V128 a = *pn, b = *pm, acc = *d, r;
    r.d[0] = 0; r.d[1] = 0;
    if (op == F_ADDP) {
        if (dbl) { r.df[0] = a.df[0] + a.df[1]; if (n == 2) r.df[1] = b.df[0] + b.df[1]; }
        else {
            for (int i = 0; i < n / 2; i++) r.f[i] = a.f[2 * i] + a.f[2 * i + 1];
            for (int i = 0; i < n / 2; i++) r.f[n / 2 + i] = b.f[2 * i] + b.f[2 * i + 1];
        }
        *d = r;
        return;
    }
    for (int i = 0; i < n; i++) {
        int is_mask = 0;
        if (dbl) {
            uint64_t m = 0;
            double v = f3d(op, acc.df[i], a.df[i], b.df[i], &m, &is_mask);
            if (is_mask) r.d[i] = m; else r.df[i] = op >= F_MAX && op <= F_MINNM ? v : fnan64(v);      /* max / min return an operand: no generated NaN to fix */
        } else {
            uint32_t m = 0;
            float v = f3s(op, acc.f[i], a.f[i], b.f[i], &m, &is_mask);
            if (is_mask) r.w[i] = m; else r.f[i] = op >= F_MAX && op <= F_MINNM ? v : fnan32(v);
        }
    }
    *d = r;
}
/* Same, with the second operand taken from one element of vm. */
static inline void v_f3e(V128 *d, const V128 *pn, const V128 *pm, int idx, int op, int dbl, int n) {
    V128 b;
    for (int i = 0; i < 4; i++) { if (dbl) b.df[i & 1] = pm->df[idx]; else b.f[i] = pm->f[idx]; }
    v_f3v(d, pn, &b, op, dbl, n);
}

enum { F1_ABS, F1_NEG, F1_SQRT, F1_RSQRTE, F1_RECPE, F1_SCVTF, F1_UCVTF, F1_CVTZS, F1_CVTZU,
       F1_CMEQ0, F1_CMGT0, F1_CMGE0, F1_CMLT0, F1_CMLE0 };

static inline void v_f1v(V128 *d, const V128 *pn, int op, int dbl, int n) {
    V128 a = *pn, r;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) {
        if (dbl) {
            double x = a.df[i];
            switch (op) {
            case F1_ABS: r.df[i] = fabs(x); break;
            case F1_NEG: r.df[i] = -x; break;
            case F1_SQRT: r.df[i] = fnan64(sqrt(x)); break;
            case F1_RSQRTE: r.df[i] = rsqrte_d(x); break;
            case F1_RECPE: r.df[i] = recpe_d(x); break;
            case F1_SCVTF: r.df[i] = (double)(int64_t)a.d[i]; break;
            case F1_UCVTF: r.df[i] = (double)a.d[i]; break;
            case F1_CVTZS: r.d[i] = f2s64(trunc(x)); break;
            case F1_CVTZU: r.d[i] = f2u64(trunc(x)); break;
            case F1_CMEQ0: r.d[i] = x == 0 ? ~0ull : 0; break;
            case F1_CMGT0: r.d[i] = x > 0 ? ~0ull : 0; break;
            case F1_CMGE0: r.d[i] = x >= 0 ? ~0ull : 0; break;
            case F1_CMLT0: r.d[i] = x < 0 ? ~0ull : 0; break;
            case F1_CMLE0: r.d[i] = x <= 0 ? ~0ull : 0; break;
            }
        } else {
            float x = a.f[i];
            switch (op) {
            case F1_ABS: r.f[i] = fabsf(x); break;
            case F1_NEG: r.f[i] = -x; break;
            case F1_SQRT: r.f[i] = fnan32(sqrtf(x)); break;
            case F1_RSQRTE: r.f[i] = rsqrte_f(x); break;
            case F1_RECPE: r.f[i] = recpe_f(x); break;
            case F1_SCVTF: r.f[i] = (float)(int32_t)a.w[i]; break;
            case F1_UCVTF: r.f[i] = (float)a.w[i]; break;
            case F1_CVTZS: r.w[i] = f2s32(trunc((double)x)); break;
            case F1_CVTZU: r.w[i] = f2u32(trunc((double)x)); break;
            case F1_CMEQ0: r.w[i] = x == 0 ? ~0u : 0; break;
            case F1_CMGT0: r.w[i] = x > 0 ? ~0u : 0; break;
            case F1_CMGE0: r.w[i] = x >= 0 ? ~0u : 0; break;
            case F1_CMLT0: r.w[i] = x < 0 ? ~0u : 0; break;
            case F1_CMLE0: r.w[i] = x <= 0 ? ~0u : 0; break;
            }
        }
    }
    *d = r;
}

enum { I_ADD, I_SUB, I_MUL, I_CMEQ, I_CMGT, I_CMHI, I_CMGE, I_CMHS, I_CMTST };

static inline void v_i3v(V128 *d, const V128 *pn, const V128 *pm, int op, int sz, int n) {
    V128 a = *pn, b = *pm, r;
    r.d[0] = 0; r.d[1] = 0;
    uint64_t ones = sz == 3 ? ~0ull : ((1ull << (8 << sz)) - 1);
    for (int i = 0; i < n; i++) {
        uint64_t x = vget(&a, sz, i), y = vget(&b, sz, i), z = 0;
        switch (op) {
        case I_ADD: z = x + y; break;
        case I_SUB: z = x - y; break;
        case I_MUL: z = x * y; break;
        case I_CMEQ: z = x == y ? ones : 0; break;
        case I_CMGT: z = vsext(x, sz) > vsext(y, sz) ? ones : 0; break;
        case I_CMGE: z = vsext(x, sz) >= vsext(y, sz) ? ones : 0; break;
        case I_CMHI: z = x > y ? ones : 0; break;
        case I_CMHS: z = x >= y ? ones : 0; break;
        case I_CMTST: z = (x & y) ? ones : 0; break;
        }
        vset(&r, sz, i, z);
    }
    *d = r;
}

enum { I1_NOT, I1_NEG, I1_ABS, I1_CMEQ0, I1_REV64, I1_CNT };

static inline void v_i1v(V128 *d, const V128 *pn, int op, int sz, int n) {
    V128 a = *pn, r;
    r.d[0] = 0; r.d[1] = 0;
    uint64_t ones = sz == 3 ? ~0ull : ((1ull << (8 << sz)) - 1);
    int per64 = 8 >> sz;
    for (int i = 0; i < n; i++) {
        uint64_t x = vget(&a, sz, i), z = 0;
        switch (op) {
        case I1_NOT: z = ~x; break;
        case I1_NEG: z = 0 - x; break;
        case I1_ABS: z = vsext(x, sz) < 0 ? 0 - x : x; break;
        case I1_CMEQ0: z = x == 0 ? ones : 0; break;
        case I1_CNT: z = (uint64_t)__builtin_popcountll(x); break;
        case I1_REV64: vset(&r, sz, (i / per64) * per64 + (per64 - 1 - i % per64), x); continue;
        }
        vset(&r, sz, i, z);
    }
    *d = r;
}

/* Narrow each element of vn to half size (XTN), low half of the destination. */
static inline void v_xtn(V128 *d, const V128 *pn, int sz) {
    V128 a = *pn, r;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < (8 >> sz); i++) vset(&r, sz, i, vget(&a, sz + 1, i));
    *d = r;
}

/* BSL / BIT / BIF */
static inline void v_bitsel(V128 *d, const V128 *pn, const V128 *pm, int kind, int q) {
    V128 r;
    for (int i = 0; i < 2; i++) {
        uint64_t x = d->d[i], n = pn->d[i], m = pm->d[i];
        r.d[i] = kind == 1 ? (x & n) | (~x & m)              /* bsl: mask in destination */
               : kind == 2 ? (x & ~m) | (n & m)              /* bit: insert if true      */
               :             (x & m) | (n & ~m);             /* bif: insert if false     */
    }
    if (!q) r.d[1] = 0;
    *d = r;
}

static inline void v_dup(V128 *d, uint64_t value, int sz, int n) {
    V128 r;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) vset(&r, sz, i, value);
    *d = r;
}

static inline void v_ext(V128 *d, const V128 *pn, const V128 *pm, int imm, int q) {
    V128 a = *pn, b = *pm, r;
    int n = q ? 16 : 8;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) r.b[i] = (imm + i < n) ? a.b[imm + i] : b.b[imm + i - n];
    *d = r;
}

/* TBL / TBX with `len` consecutive table registers starting at index rn. */
static inline void v_tbl(Ctx *c, int rd, int rn, int len, int rm, int q, int tbx) {
    uint8_t table[64];
    for (int i = 0; i < len; i++) memcpy(table + 16 * i, c->v[(rn + i) & 31].b, 16);
    V128 idx = c->v[rm], r = c->v[rd];
    int n = q ? 16 : 8;
    for (int i = 0; i < n; i++) {
        if (idx.b[i] < 16 * len) r.b[i] = table[idx.b[i]];
        else if (!tbx) r.b[i] = 0;
    }
    if (!q) r.d[1] = 0;
    c->v[rd] = r;
}

/* LDn / STn multiple structures (n = 2..4): elements are interleaved in memory,
 * element i of register k lives at memory element (i * n + k). */
static inline void v_ldn(Ctx *c, uint64_t a, int rt, int n, int sz, int q) {
    int count = (q ? 16 : 8) >> sz, es = 1 << sz;
    V128 r[4];
    for (int k = 0; k < n; k++) { r[k].d[0] = 0; r[k].d[1] = 0; }
    for (int i = 0; i < count; i++)
        for (int k = 0; k < n; k++) {
            uint64_t v = 0;
            memcpy(&v, (void *)(uintptr_t)(a + (uint64_t)((i * n + k) * es)), (size_t)es);
            vset(&r[k], sz, i, v);
        }
    for (int k = 0; k < n; k++) c->v[(rt + k) & 31] = r[k];
}
static inline void v_stn(Ctx *c, uint64_t a, int rt, int n, int sz, int q) {
    int count = (q ? 16 : 8) >> sz, es = 1 << sz;
    for (int i = 0; i < count; i++)
        for (int k = 0; k < n; k++) {
            uint64_t v = vget(&c->v[(rt + k) & 31], sz, i);
            R1M(a + (uint64_t)((i * n + k) * es), (uint64_t)es);
            memcpy((void *)(uintptr_t)(a + (uint64_t)((i * n + k) * es)), &v, (size_t)es);
        }
}

/* UZP1/TRN1/ZIP1/UZP2/TRN2/ZIP2: opcode is bits 14:12 of the instruction. */
static inline void v_perm(V128 *d, const V128 *pn, const V128 *pm, int opcode, int sz, int n) {
    V128 a = *pn, b = *pm, r;
    int part = (opcode >> 2) & 1, kind = opcode & 3, half = n / 2;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < half; i++) {
        uint64_t lo, hi;
        if (kind == 1) {                                     /* uzp */
            lo = vget(&a, sz, 2 * i + part);
            hi = vget(&b, sz, 2 * i + part);
            vset(&r, sz, i, lo);
            vset(&r, sz, half + i, hi);
        } else if (kind == 2) {                              /* trn */
            vset(&r, sz, 2 * i, vget(&a, sz, 2 * i + part));
            vset(&r, sz, 2 * i + 1, vget(&b, sz, 2 * i + part));
        } else {                                             /* zip */
            vset(&r, sz, 2 * i, vget(&a, sz, part * half + i));
            vset(&r, sz, 2 * i + 1, vget(&b, sz, part * half + i));
        }
    }
    *d = r;
}

/* SSHLL/USHLL (also SXTL/UXTL): widen the low (or high) half and shift left. */
static inline void v_shll(V128 *d, const V128 *pn, int shift, int sz, int is_unsigned, int upper) {
    V128 a = *pn, r;
    int n = 8 >> sz;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) {
        uint64_t x = vget(&a, sz, i + (upper ? n : 0));
        vset(&r, sz + 1, i, (is_unsigned ? x : (uint64_t)vsext(x, sz)) << shift);
    }
    *d = r;
}
/* SHL / SSHR / USHR by immediate. kind: 0 shl, 1 sshr, 2 ushr. */
static inline void v_shift(V128 *d, const V128 *pn, int shift, int sz, int kind, int n) {
    V128 a = *pn, r;
    int bits = 8 << sz;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) {
        uint64_t x = vget(&a, sz, i), z;
        if (kind == 0) z = x << shift;
        else if (kind == 1) z = (uint64_t)(vsext(x, sz) >> (shift >= bits ? bits - 1 : shift));
        else z = shift >= bits ? 0 : x >> shift;
        vset(&r, sz, i, z);
    }
    *d = r;
}

/* ---- Instructions the game's code does not use (they appear in Rust-compiled modules, e.g. Skyline plugins). Added
 * after the existing helpers, which do not change. Same rules: element by element, the upper half of a 64-bit (Q = 0)
 * destination cleared. */

/* Integer three-same additions. SSHL / USHL: shift by the signed low byte of each element of vm (negative: right,
 * arithmetic for SSHL); SMAX..UMIN; the pairwise forms (ADDP, SMAXP..UMINP) work on the concatenation vm:vn. */
enum { IX_SSHL, IX_USHL, IX_SMAX, IX_UMAX, IX_SMIN, IX_UMIN, IX_ADDP, IX_SMAXP, IX_UMAXP, IX_SMINP, IX_UMINP };

static inline uint64_t ix_op(int op, uint64_t x, uint64_t y, int sz) {
    int bits = 8 << sz;
    switch (op) {
    case IX_SSHL: case IX_USHL: {
        int s = (int8_t)y;
        if (s >= 0) return s >= bits ? 0 : x << s;
        s = -s;
        if (op == IX_USHL) return s >= bits ? 0 : x >> s;
        return (uint64_t)(vsext(x, sz) >> (s >= bits ? bits - 1 : s));
    }
    case IX_SMAX: case IX_SMAXP: return vsext(x, sz) > vsext(y, sz) ? x : y;
    case IX_UMAX: case IX_UMAXP: return x > y ? x : y;
    case IX_SMIN: case IX_SMINP: return vsext(x, sz) < vsext(y, sz) ? x : y;
    case IX_UMIN: case IX_UMINP: return x < y ? x : y;
    case IX_ADDP: return x + y;
    }
    return 0;
}
static inline void v_i3x(V128 *d, const V128 *pn, const V128 *pm, int op, int sz, int n) {
    V128 a = *pn, b = *pm, r;
    r.d[0] = 0; r.d[1] = 0;
    if (op >= IX_ADDP) {
        int half = n / 2;
        for (int i = 0; i < half; i++) {
            vset(&r, sz, i, ix_op(op, vget(&a, sz, 2 * i), vget(&a, sz, 2 * i + 1), sz));
            vset(&r, sz, half + i, ix_op(op, vget(&b, sz, 2 * i), vget(&b, sz, 2 * i + 1), sz));
        }
    } else {
        for (int i = 0; i < n; i++) vset(&r, sz, i, ix_op(op, vget(&a, sz, i), vget(&b, sz, i), sz));
    }
    *d = r;
}

/* Compare signed elements with zero: CMGT / CMGE / CMLE / CMLT #0 (CMEQ #0 is I1_CMEQ0). */
enum { I1X_CMGT0, I1X_CMGE0, I1X_CMLE0, I1X_CMLT0 };

static inline void v_i1x(V128 *d, const V128 *pn, int op, int sz, int n) {
    V128 a = *pn, r;
    r.d[0] = 0; r.d[1] = 0;
    uint64_t ones = sz == 3 ? ~0ull : ((1ull << (8 << sz)) - 1);
    for (int i = 0; i < n; i++) {
        int64_t x = vsext(vget(&a, sz, i), sz);
        int t = op == I1X_CMGT0 ? x > 0 : op == I1X_CMGE0 ? x >= 0 : op == I1X_CMLE0 ? x <= 0 : x < 0;
        vset(&r, sz, i, t ? ones : 0);
    }
    *d = r;
}

/* SADDLP / UADDLP / SADALP / UADALP: adjacent pairs of sz elements added into n elements of size sz + 1 (and, for the
 * accumulating forms, added to the destination's elements). */
static inline void v_addlp(V128 *d, const V128 *pn, int sz, int is_unsigned, int acc, int n) {
    V128 a = *pn, o = *d, r;
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) {
        uint64_t x = vget(&a, sz, 2 * i), y = vget(&a, sz, 2 * i + 1);
        uint64_t s = is_unsigned ? x + y : (uint64_t)(vsext(x, sz) + vsext(y, sz));
        vset(&r, sz + 1, i, s + (acc ? vget(&o, sz + 1, i) : 0));
    }
    *d = r;
}

/* Across all n elements, result in element 0 (size sz, or sz + 1 for the long sums), the rest of vd cleared. */
enum { AX_ADDV, AX_SADDLV, AX_UADDLV, AX_SMAXV, AX_UMAXV, AX_SMINV, AX_UMINV };

static inline void v_across(V128 *d, const V128 *pn, int op, int sz, int n) {
    V128 a = *pn, r;
    r.d[0] = 0; r.d[1] = 0;
    uint64_t acc = vget(&a, sz, 0);
    int64_t sacc = vsext(acc, sz);
    for (int i = 1; i < n; i++) {
        uint64_t x = vget(&a, sz, i);
        int64_t sx = vsext(x, sz);
        switch (op) {
        case AX_ADDV: case AX_UADDLV: acc += x; break;
        case AX_SADDLV: sacc += sx; break;
        case AX_SMAXV: if (sx > sacc) { sacc = sx; acc = x; } break;
        case AX_UMAXV: if (x > acc) acc = x; break;
        case AX_SMINV: if (sx < sacc) { sacc = sx; acc = x; } break;
        case AX_UMINV: if (x < acc) acc = x; break;
        }
    }
    if (op == AX_SADDLV) vset(&r, sz + 1, 0, (uint64_t)sacc);
    else vset(&r, op == AX_UADDLV ? sz + 1 : sz, 0, acc);
    *d = r;
}

/* FMAXNMV / FMINNMV / FMAXV / FMINV, 4 singles: Reduce() of the Arm manual pairs the halves, op(op(e0, e1), op(e2, e3)). */
static inline void v_facross(V128 *d, const V128 *pn, int is_min, int num) {
    V128 a = *pn;
    uint32_t lo = fp_maxmin32_bits(a.w[0], a.w[1], is_min, num), hi = fp_maxmin32_bits(a.w[2], a.w[3], is_min, num);
    uint32_t t = fp_maxmin32_bits(lo, hi, is_min, num);
    vzero(d);
    d->w[0] = t;
}

/* Shifts by immediate. kind: SSRA / USRA (shift right and accumulate), SRSHR / URSHR (rounding), SRSRA / URSRA (both),
 * SRI / SLI (shift and insert: the destination keeps the bits the shift brings in). Right shifts are 1..esize. */
enum { SX_SSRA, SX_USRA, SX_SRSHR, SX_URSHR, SX_SRSRA, SX_URSRA, SX_SRI, SX_SLI };

static inline void v_shiftx(V128 *d, const V128 *pn, int shift, int sz, int kind, int n) {
    V128 a = *pn, o = *d, r;
    int bits = 8 << sz;
    uint64_t ones = sz == 3 ? ~0ull : ((1ull << bits) - 1);
    r.d[0] = 0; r.d[1] = 0;
    for (int i = 0; i < n; i++) {
        uint64_t x = vget(&a, sz, i), dv = vget(&o, sz, i), z = 0, m;
        switch (kind) {
        case SX_SSRA: z = dv + (uint64_t)(vsext(x, sz) >> (shift >= bits ? bits - 1 : shift)); break;
        case SX_USRA: z = dv + (shift >= bits ? 0 : x >> shift); break;
        case SX_SRSHR: case SX_SRSRA:
            z = (uint64_t)(int64_t)(((__int128)vsext(x, sz) + ((__int128)1 << (shift - 1))) >> shift);
            if (kind == SX_SRSRA) z += dv;
            break;
        case SX_URSHR: case SX_URSRA:
            z = (uint64_t)(((unsigned __int128)x + ((unsigned __int128)1 << (shift - 1))) >> shift);
            if (kind == SX_URSRA) z += dv;
            break;
        case SX_SRI:
            if (shift >= bits) { z = dv; break; }
            m = ones >> shift;
            z = (dv & ~m) | (x >> shift);
            break;
        case SX_SLI:
            m = (ones << shift) & ones;
            z = (dv & ~m) | ((x << shift) & m);
            break;
        }
        vset(&r, sz, i, z);
    }
    *d = r;
}

/* SHRN / RSHRN (and the "2" forms, upper = 1: written to the upper half, the lower half of vd kept): elements of size
 * sz + 1 shifted right (1..esize, rounding for RSHRN) and narrowed to size sz. */
static inline void v_shrn(V128 *d, const V128 *pn, int shift, int sz, int round, int upper) {
    V128 a = *pn, r;
    int n = 8 >> sz;
    r.d[0] = upper ? d->d[0] : 0;
    r.d[1] = 0;
    for (int i = 0; i < n; i++) {
        unsigned __int128 x = vget(&a, sz + 1, i);
        if (round) x += (unsigned __int128)1 << (shift - 1);
        vset(&r, sz, (upper ? n : 0) + i, (uint64_t)(x >> shift));
    }
    *d = r;
}

/* FCVTL / FCVTL2: widen the lower (upper = 1: upper) half, half -> single (dbl = 0) or single -> double (dbl = 1).
 * FCVTN / FCVTN2: narrow, single -> half or double -> single, into the lower half (FCVTN2: the upper half, lower kept).
 * Half precision through fpexact.h; single <-> double are the host's conversions (as the scalar FCVT), which round to
 * nearest and quiet a NaN keeping the top of its payload, like FPConvert with FPCR.DN = 0. */
static inline void v_fcvtl(V128 *d, const V128 *pn, int dbl, int upper) {
    V128 a = *pn, r;
    if (dbl) for (int i = 0; i < 2; i++) r.df[i] = (double)a.f[i + 2 * upper];
    else for (int i = 0; i < 4; i++) r.f[i] = half_to_f32(a.h[i + 4 * upper]);
    *d = r;
}
static inline void v_fcvtn(V128 *d, const V128 *pn, int dbl, int upper) {
    V128 a = *pn, r;
    r.d[0] = upper ? d->d[0] : 0;
    r.d[1] = 0;
    if (dbl) for (int i = 0; i < 2; i++) r.f[i + 2 * upper] = (float)a.df[i];
    else for (int i = 0; i < 4; i++) r.h[i + 4 * upper] = f32_to_half(a.f[i]);
    *d = r;
}

#endif
